Boolean vrtc_init( void )
{    
	static Boolean do_one_time = TRUE ; 

	if( do_one_time )
	{
		vrtc_table 	   = reg_table_create( REG_ATOMIC_USE_IRQ ) ; 
	
		rtc_init( (Rtc_Func)vrtc_service );

		do_one_time = FALSE ; 
				
	}
	
	return !!vrtc_table ; 
}

